      out.write("\n");
      out.write("<script>\n");
      out.write("(function() {\n");
      out.write("    'use strict';\n");
      out.write("\n");
      out.write("    var video = document.getElementById('vnLiveSkyVideo');\n");
      out.write("    var dayEl = document.getElementById('vnLandscapeDay');\n");
      out.write("    var nightEl = document.getElementById('vnLandscapeNight');\n");
      out.write("    var nightEffects = document.getElementById('vnNightEffects');\n");
      out.write("    var starsWrapper = document.getElementById('vnStarsWrapper');\n");
      out.write("    var shootingStar = document.getElementById('vnShootingStar');\n");
      out.write("\n");
      out.write("    // 1. Hàm lấy giờ Việt Nam (UTC+7) chuẩn xác\n");
      out.write("    function getVietnamDecHour() {\n");
      out.write("        var now = new Date();\n");
      out.write("        var utcMs = now.getTime() + (now.getTimezoneOffset() * 60000);\n");
      out.write("        var vnDate = new Date(utcMs + (7 * 3600000));\n");
      out.write("        return vnDate.getHours() + (vnDate.getMinutes() / 60) + (vnDate.getSeconds() / 3600);\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    // 2. Tạo 45 ngôi sao lấp lánh ban đêm\n");
      out.write("    if (starsWrapper && starsWrapper.children.length === 0) {\n");
      out.write("        var frag = document.createDocumentFragment();\n");
      out.write("        for (var i = 0; i < 45; i++) {\n");
      out.write("            var s = document.createElement('div');\n");
      out.write("            s.className = 'vn-star';\n");
      out.write("            var sz = (Math.random() * 2 + 1.2).toFixed(1);\n");
      out.write("            s.style.width = sz + 'px';\n");
      out.write("            s.style.height = sz + 'px';\n");
      out.write("            s.style.left = (Math.random() * 96 + 2).toFixed(2) + '%';\n");
      out.write("            s.style.top = (Math.random() * 45 + 2).toFixed(2) + '%';\n");
      out.write("            s.style.animationDelay = (Math.random() * 4).toFixed(2) + 's';\n");
      out.write("            s.style.animationDuration = (Math.random() * 3 + 2.5).toFixed(2) + 's';\n");
      out.write("            frag.appendChild(s);\n");
      out.write("        }\n");
      out.write("        starsWrapper.appendChild(frag);\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    // 3. Sao băng tự động về đêm\n");
      out.write("    function launchShootingStar() {\n");
      out.write("        if (!shootingStar) return;\n");
      out.write("        var decH = getVietnamDecHour();\n");
      out.write("        if (decH >= 18.5 || decH <= 5.5) {\n");
      out.write("            shootingStar.style.top = (Math.random() * 30 + 5) + '%';\n");
      out.write("            shootingStar.style.left = (Math.random() * 60 + 5) + '%';\n");
      out.write("            shootingStar.classList.remove('active');\n");
      out.write("            void shootingStar.offsetWidth;\n");
      out.write("            shootingStar.classList.add('active');\n");
      out.write("        }\n");
      out.write("        var nextDelay = Math.random() * 9000 + 7000;\n");
      out.write("        setTimeout(launchShootingStar, nextDelay);\n");
      out.write("    }\n");
      out.write("    setTimeout(launchShootingStar, 3000);\n");
      out.write("\n");
      out.write("    // Mốc chuẩn người dùng cung cấp: Lúc 20h24 (20.4h) tối tương đương giây thứ 13.0 trong video\n");
      out.write("    var REF_HOUR = 20.4;    // 20h24 tối\n");
      out.write("    var REF_SECOND = 13.0;  // Giây thứ 13.0 trong video\n");
      out.write("\n");
      out.write("    // 4. Tính giây mục tiêu trong video (chu kỳ 24 giờ khớp chuẩn xác mốc 20h24 = 13s)\n");
      out.write("    function calculateTargetSecond(duration) {\n");
      out.write("        if (!duration || isNaN(duration)) duration = 60.0;\n");
      out.write("        var decH = getVietnamDecHour();\n");
      out.write("        var rate = duration / 24.0; // 2.5 giây cho mỗi 1 giờ thực tế\n");
      out.write("        var deltaH = decH - REF_HOUR;\n");
      out.write("        var targetSec = REF_SECOND + (deltaH * rate);\n");
      out.write("        targetSec = ((targetSec % duration) + duration) % duration;\n");
      out.write("        return targetSec;\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    // 5. Cập nhật trạng thái ngày/đêm & video\n");
      out.write("    function syncRealtimeState() {\n");
      out.write("        var decH = getVietnamDecHour();\n");
      out.write("        var isNight = (decH >= 18.5 || decH < 5.5);\n");
      out.write("\n");
      out.write("        // Hiệu ứng đêm\n");
      out.write("        if (nightEffects) {\n");
      out.write("            nightEffects.style.opacity = isNight ? '1' : '0';\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Cập nhật fallback poster\n");
      out.write("        if (dayEl && nightEl) {\n");
      out.write("            if (decH >= 6.5 && decH < 17.5) {\n");
      out.write("                dayEl.style.opacity = '1';\n");
      out.write("                nightEl.style.opacity = '0';\n");
      out.write("            } else if (decH >= 17.5 && decH < 18.5) {\n");
      out.write("                var t = (decH - 17.5);\n");
      out.write("                dayEl.style.opacity = (1 - t).toFixed(2);\n");
      out.write("                nightEl.style.opacity = t.toFixed(2);\n");
      out.write("            } else if (isNight) {\n");
      out.write("                dayEl.style.opacity = '0';\n");
      out.write("                nightEl.style.opacity = '1';\n");
      out.write("            } else {\n");
      out.write("                var t2 = (decH - 5.5);\n");
      out.write("                dayEl.style.opacity = t2.toFixed(2);\n");
      out.write("                nightEl.style.opacity = (1 - t2).toFixed(2);\n");
      out.write("            }\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        // Đồng bộ vị trí video theo thời gian thực\n");
      out.write("        if (video && video.duration && !isNaN(video.duration)) {\n");
      out.write("            var targetSec = calculateTargetSecond(video.duration);\n");
      out.write("            // Nếu chênh lệch hơn 0.5s thì đồng bộ lại\n");
      out.write("            if (Math.abs(video.currentTime - targetSec) > 0.5) {\n");
      out.write("                video.currentTime = targetSec;\n");
      out.write("            }\n");
      out.write("        }\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    // 6. Xử lý video khi sẵn sàng\n");
      out.write("    if (video) {\n");
      out.write("        function onVideoReady() {\n");
      out.write("            video.classList.add('ready');\n");
      out.write("            syncRealtimeState();\n");
      out.write("        }\n");
      out.write("\n");
      out.write("        video.addEventListener('loadedmetadata', function() {\n");
      out.write("            var targetSec = calculateTargetSecond(video.duration);\n");
      out.write("            video.currentTime = targetSec;\n");
      out.write("            onVideoReady();\n");
      out.write("        });\n");
      out.write("\n");
      out.write("        video.addEventListener('canplay', function() {\n");
      out.write("            onVideoReady();\n");
      out.write("        });\n");
      out.write("\n");
      out.write("        // Nếu video đã cached sẵn\n");
      out.write("        if (video.readyState >= 1) {\n");
      out.write("            onVideoReady();\n");
      out.write("        }\n");
      out.write("    }\n");
      out.write("\n");
      out.write("    // Chạy đồng bộ ngay lập tức\n");
      out.write("    syncRealtimeState();\n");
      out.write("\n");
      out.write("    // Tự động kiểm tra và đồng bộ liên tục mỗi 2 giây\n");
      out.write("    setInterval(syncRealtimeState, 2000);\n");
      out.write("})();\n");
      out.write("</script>\n");
